  #bomb-status.bomb-info { color: var(--ink); }

  /* Top-right: killfeed. */
  #killfeed { position: fixed; top: 18px; right: 32px; text-align: right; font-family: var(--font-readout); font-size: 13px; display: grid; gap: 4px; }
