  #banner-sub { font-size: 16px; color: var(--muted); margin-top: 4px; text-shadow: 0 1px 6px rgba(0,0,0,.7); }
  #hint { position: fixed; bottom: 110px; left: 50%; transform: translateX(-50%); font-size: 14px; color: var(--ink);
    background: rgba(42, 47, 56, .85); padding: 6px 12px; border-radius: 4px; }

  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 86%, transparent); }
  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 500; letter-spacing: -0.02em; }
  .panel h1 .accent { color: var(--accent); }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--muted); }
  #play { font: inherit; font-weight: 500; padding: 12px 16px; border: 1px solid var(--accent); border-radius: var(--radius-control);
    background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  #play:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel);
    font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }

  /* Buy menu, right side, pointer-events on so rows are clickable. */
  #buy-menu { position: fixed; top: 50%; right: 32px; transform: translateY(-50%); width: 320px; pointer-events: auto;
    background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); padding: 16px; }
  #buy-menu[hidden] { display: none; }
  #buy-menu h2 { margin: 0 0 4px; font-size: 18px; font-weight: 500; }
  #buy-menu h2 span { color: var(--accent); font-family: var(--font-readout); }
  #buy-menu .sub { font-size: 13px; color: var(--muted); margin-bottom: 12px; }
  .buy-row { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; margin-top: 4px;
    background: transparent; border: 1px solid var(--hairline); border-radius: 4px; color: var(--ink);
    font: inherit; font-size: 14px; cursor: pointer; text-align: left; }
  .buy-row:hover { border-color: var(--accent); background: rgba(240, 168, 48, .08); }
  .buy-key { font-family: var(--font-readout); font-size: 12px; color: var(--accent); border: 1px solid var(--hairline);
    border-radius: 3px; padding: 1px 6px; }
  .buy-label { flex: 1; }
  .buy-price { font-family: var(--font-readout); color: var(--muted); }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #play, #damage-vignette, #flash-overlay { transition-duration: 0.01ms; }
  }
</style>
</head>
