    defenders[1].role = 'holdB';
    defenders[1].holdNode = 17;
    defenders[2].role = 'holdA';
    defenders[2].holdNode = 23;
    defenders[3].role = 'holdB';
    defenders[3].holdNode = 24;
    defenders[4].role = 'roam';
